import "sync/atomic"

var refs atomic.Int64

func tryAcquire() bool { return refs.CompareAndSwap(0, 1) }

// publish immutable state: store the pointer atomically
type node struct { next *node; v int }
var head atomic.Pointer[node]

func push(n *node) {
    for {
        old := head.Load()
        n.next = old
        if head.CompareAndSwap(old, n) { return }
        runtime.Gosched()          // backoff: yield rather than spin hot
    }
}

// a channel send is itself a synchronisation event per the Go memory model
func handoff(ch chan int, v int) { ch <- v }   // happens-before the matching receive
